/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_mcp_validate_refs_before_insert` BEFORE INSERT ON `machine_centre_production` FOR EACH ROW BEGIN IF NOT EXISTS (SELECT 1 FROM machine_centres WHERE machine_id = NEW.machine_id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Invalid machine_id for machine_centre_production'; END IF; IF NOT EXISTS (SELECT 1 FROM employees WHERE code = NEW.emp_id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Invalid emp_id for machine_centre_production'; END IF; END */;;
DELIMITER ;
