/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_mcp_before_insert_set_prod_date` BEFORE INSERT ON `machine_centre_production` FOR EACH ROW BEGIN IF NEW.prod_date IS NULL THEN IF NEW.start_time IS NULL THEN SET NEW.prod_date = DATE(NOW()); ELSE SET NEW.prod_date = DATE(NEW.start_time); END IF; END IF; END */;;
